
ALTER TABLE public.scam_alerts ADD COLUMN story TEXT;

UPDATE public.scam_alerts SET story = 'TradeWave Markets has been flagged after multiple users reported withdrawal refusals following profitable trades. A total of $12,400 remains unresolved across 8 verified complaints. Users report that the platform initially processes deposits within minutes but stalls withdrawals with repeated "verification" requests. Several traders have provided screenshots showing approved withdrawal requests that were later cancelled without explanation. The pattern suggests systematic withdrawal denial targeting profitable accounts. Our investigation team has reached out to TradeWave Markets for comment but has received no response as of this writing.' WHERE title = 'TradeWave Markets';

UPDATE public.scam_alerts SET story = 'GoldFX Pro has been identified as operating with falsified regulatory credentials. Investigation reveals the platform displays fake FCA and CySEC license numbers that do not correspond to any registered entity. Platform manipulation has been reported by 12 users, with evidence of spread widening during high-impact news events beyond normal market conditions. A combined $8,200 is currently under investigation. Multiple users have shared screen recordings showing price feed discrepancies between GoldFX Pro and legitimate brokers during the same timeframes. Regulatory bodies have been notified and an official warning is expected.' WHERE title = 'GoldFX Pro';

UPDATE public.scam_alerts SET story = 'CryptoEdge BD has frozen multiple user accounts without prior notice or explanation. At least 5 users have reported being locked out of their accounts for over 30 days with no response from customer support. The total amount held in frozen accounts is approximately $3,800. Users report that support tickets go unanswered and live chat representatives provide scripted responses with no resolution timeline. The platform continues to accept new deposits while existing users remain unable to access their funds. We recommend avoiding this platform until the situation is resolved.' WHERE title = 'CryptoEdge BD';
